 examples:[{q:L('A ball: h(t) = −5t² + 30t. Maximum height?','Доп: h(t) = −5t² + 30t. Ең үлкен биіктік?','Мяч: h(t) = −5t² + 30t. Наибольшая высота?'),steps:['t_0 = 3','h(3) = -45 + 90 = 45 m']},{q:L('40 m of fence along a wall. Largest area?','Қабырға бойымен 40 м қоршау. Ең үлкен аудан?','40 м забора у стены. Наибольшая площадь?'),steps:['S(x) = x(40 - 2x)','x_0 = 10','S = 10*20 = 200 m^2']}],
